    .pbr_stepper ul.stepper:before {
      content: none
    }

    .pbr_stepper ul.stepper.horizontal .step:before {
      display: none
    }

    .pbr_stepper ul.stepper.horizontal .step:after {
      display: none
    }

    .pbr_stepper ul.stepper.horizontal .step:not(:last-of-type) .step-progress:after {
      background-color: #2c2cd6;
      content: "";
      display: block;
      width: 100%;
      height: 3px;
      transform: translate(50%, 15px)
    }

    .pbr_stepper ul.stepper.horizontal .step-title:hover {
      background: none
    }

    .pbr_stepper ul.stepper.horizontal .step-title:before {
      background-color: #2c2cd6;
      color: #111158;
      position: absolute;
      counter-increment: section;
      content: counter(section);
      height: 28px;
      width: 28px;
      border-radius: 50%;
      text-align: center;
      line-height: 28px;
      font-weight: 400;
      font-size: 15px;
      top: 0;
      left: 50%;
      transform: translateX(-50%)
    }

    .pbr_stepper ul.stepper.horizontal .step.active .step-progress:after {
      background-image: linear-gradient(to right, #111158, #2c2cd6)
    }

    .pbr_stepper ul.stepper.horizontal .step.active .step-title:before {
      background-color: #111158;
      color: #ffffff
    }

    .pbr_stepper ul.stepper.horizontal .step.active:after {
      display: none
    }

    .pbr_stepper ul.stepper.horizontal .step.done .step-progress:after {
      background-color: #111158 !important
    }

