    .list-item.bordered:before {
      background-color: #E6E7E8
    }

    .list-item-message-summary.selected:after {
      content: "";
      position: absolute;
      right: 0;
      top: 0;
      bottom: 0;
      width: 15px;
      background-image: url(data:image/svg+xml;charset=utf8,%3Csvg\ width=\'14\'\ height=\'14\'\ viewBox=\'0\ 0\ 100\ 100\'\
							xmlns=\'http://www.w3.org/2000/svg\'\
							xmlns:xlink=\'http://www.w3.org/1999/xlink\'%3E%3Cpolygon\ fill=\'%23fff\'\ points=\'100,0\ 50,50\ 100,100\'/%3E%3C/svg%3E);
      background-repeat: no-repeat;
      background-size: 14px 14px;
      background-position: right center;
      border-right: 3px solid #ffffff
    }

    .list-item-radio [type=radio]+label:before,
    .list-item-radio [type=radio]+label:after {
      width: 21px;
      height: 21px;
      transform: translateY(-20%);
      border: 6px solid #00002E
    }

    .list-item-radio [type=radio]+label:after {
      background-color: #ffffff
    }

    .list-item-radio [type=radio]:not(:checked)+label:before,
    .list-item-radio [type=radio]:not(:checked)+label:after {
      border: 2px solid rgba(50, 50, 50, 0.75)
    }

    .list-item-portefeuille__wrapper .operation__info--title:after {
      position: absolute;
      content: "";
      top: 0;
      right: 0;
      bottom: 0;
      width: 56px;
      background-image: linear-gradient(-90deg, rgb(255, 255, 255) 0%, rgba(255, 255, 255, 0.5) 80%, rgba(255, 255, 255, 0) 100%)
    }

    @media only screen and (min-width:1200px) {
      .list-item-portefeuille__wrapper .operation__info--title:after {
        display: none
      }
    }

    .modal.modal-calculator #calculator .btn:hover,
    .modal.modal-calculator #calculator .btn-large:hover {
      opacity: 0.9
    }

    .modal.modal-calculator #calculator .btn:focus,
    .modal.modal-calculator #calculator .btn-large:focus {
      color: #ffffff !important;
      background-color: #00002E !important
    }

    .modal.modal-calculator #calculator .btn.calculation:focus,
    .modal.modal-calculator #calculator .calculation.btn-large:focus {
      color: #ffffff !important;
      background-color: rgba(0, 0, 46, 0.75) !important
    }

    .modal.modal-calculator #calculator .btn.equals:focus,
    .modal.modal-calculator #calculator .equals.btn-large:focus {
      color: #ffffff !important;
      background-color: #122242 !important
    }

    .modal.modal-calculator #calculator .btn.c-btn:focus,
    .modal.modal-calculator #calculator .c-btn.btn-large:focus,
    .modal.modal-calculator #calculator .btn.b-btn:focus,
    .modal.modal-calculator #calculator .b-btn.btn-large:focus {
      color: #ffffff !important;
      background-color: rgba(18, 34, 66, 0.75) !important
    }

    .modal.modal-calculator #calculator .btn.validate:focus,
    .modal.modal-calculator #calculator .validate.btn-large:focus {
      color: #00002E !important;
      background-color: #ffffff !important
    }

    .map-legend__map:before {
      content: "";
      display: block;
      padding-bottom: 118.75%
    }

    .multiple-bloc button.multiple-bloc__close:hover {
      box-shadow: none
    }

    .portfolio-overview__valuation .content .card__overview--global-card>.row.exchange-rate-overview:nth-child(n+2):before {
      content: "";
      display: block;
      margin: 0 auto;
      width: 95%;
      border-bottom: 1px solid rgba(50, 50, 50, 0.25)
    }

    @media only screen and (max-width:1199px) {
      .portfolio-overview__valuation .content .variations-overview__item:first-child:after {
        content: "";
        display: block;
        margin: 0 auto;
        width: 90%;
        padding-top: 15px;
        border-bottom: 1px solid rgba(50, 50, 50, 0.25)
      }
    }

    .product-card:before {
      content: "";
      display: block
    }

    .product-card-slide-item__image:before {
      content: "";
      display: block
    }

    .push-marketing:before {
      content: "";
      display: block;
      padding-bottom: 52.5%
    }

